// PPTX导出模块 - 使用pptxgenjs最简方式
var PptxGenLib = null;

// 加载pptxgenjs
function loadPptxGenJS() {
    return new Promise(function(resolve, reject) {
        if (window.PptxGenJS) {
            resolve(window.PptxGenJS);
            return;
        }
        var s = document.createElement('script');
        s.src = chrome.runtime.getURL('bundles/pptxgen.bundle.min.js');
        s.onload = function() { resolve(window.PptxGenJS); };
        s.onerror = function() { reject(new Error('PPT库加载失败')); };
        document.head.appendChild(s);
    });
}

// 导出PPT
async function exportToPPT(steps) {
    try {
        console.log('[PPT] Starting...');
        
        // 加载库
        var PptxGenJS = await loadPptxGenJS();
        
        // 创建PPT
        var pptx = new PptxGenJS();
        
        // 标题页
        var slide1 = pptx.addSlide();
        slide1.addText('操作步骤文档', {
            x: 1, y: 2.5, w: 8.5, h: 1,
            fontSize: 36, bold: true, color: '333333'
        });
        slide1.addText('生成时间: ' + new Date().toLocaleString('zh-CN'), {
            x: 1, y: 3.8, w: 8.5, h: 0.5,
            fontSize: 14, color: '666666'
        });
        slide1.addText('总步骤数: ' + steps.length, {
            x: 1, y: 4.3, w: 8.5, h: 0.5,
            fontSize: 14, color: '666666'
        });
        
        // 步骤页
        for (var i = 0; i < steps.length; i++) {
            var step = steps[i];
            if (!step) continue;
            
            var slide = pptx.addSlide();
            
            // 标题
            var title = step.title ? String(step.title) : ('步骤 ' + (i + 1));
            slide.addText(title, {
                x: 0.5, y: 0.3, w: 9, h: 0.6,
                fontSize: 20, bold: true, color: '333333'
            });
            
            // 图片
            if (step.screenshot && typeof step.screenshot === 'string' && step.screenshot.indexOf('data:') === 0) {
                try {
                    slide.addImage({ data: step.screenshot, x: 0.5, y: 1.0, w: 9, h: 5 });
                } catch (e) {
                    console.error('[PPT] Image error:', e);
                }
            }
            
            // 时间戳
            if (step.timestamp) {
                var t = '';
                try { t = new Date(step.timestamp).toLocaleString('zh-CN'); } catch(e) {}
                if (t && t !== 'Invalid Date') {
                    slide.addText(t, {
                        x: 0.5, y: 6.2, w: 9, h: 0.3,
                        fontSize: 10, color: '999999'
                    });
                }
            }
        }
        
        // 生成文件
        var blob = await pptx.write({ type: 'blob' });
        
        // 文件名
        var now = new Date();
        var fname = 'SnapScribe_' + now.getFullYear() + pad(now.getMonth()+1) + pad(now.getDate()) + '_' + pad(now.getHours()) + pad(now.getMinutes()) + '.pptx';
        
        // 下载
        var reader = new FileReader();
        return new Promise(function(resolve, reject) {
            reader.onload = function() {
                chrome.runtime.sendMessage({
                    action: 'downloadFile',
                    data: { dataUrl: reader.result, filename: fname }
                }, function() {
                    console.log('[PPT] Done');
                    resolve({ success: true, filename: fname });
                });
            };
            reader.onerror = function() { reject(new Error('下载失败')); };
            reader.readAsDataURL(blob);
        });
        
    } catch (err) {
        console.error('[PPT] Error:', err);
        throw err;
    }
}

function pad(n) { return n < 10 ? '0' + n : '' + n; }

// 入口
async function handlePPTExport() {
    await exportToPPT(steps.slice());
}
